<template><section class="lms-page"><div class="page-head"><button class="lms-btn" @click="$router.back()">← Quay lại</button><div><h1>Kết quả bài tập</h1><p>Xem điểm hệ thống và lịch sử làm bài.</p></div></div><div class="card"><h3>Kết quả hiện tại</h3><p v-if="!ketQua">Chưa có kết quả.</p><template v-else><div class="score">{{ formatDiem(ketQua.diemCuoiCung) }}</div><p>Trạng thái: {{ TRANG_THAI_KET_QUA[ketQua.trangThai] || ketQua.trangThai }}</p><p>Nhận xét: {{ ketQua.nhanXet || '—' }}</p></template></div><div class="card"><h3>Lịch sử lần làm</h3><table><thead><tr><th>Lần</th><th>Bắt đầu</th><th>Nộp</th><th>Điểm</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="l in lichSu" :key="l.id"><td>{{ l.lanThu }}</td><td>{{ formatDateTime(l.thoiGianBatDau) }}</td><td>{{ formatDateTime(l.thoiGianNop) }}</td><td>{{ formatDiem(l.diemCuoiCung) }}</td><td>{{ TRANG_THAI_LAN_LAM_BAI[l.trangThai] || l.trangThai }}</td></tr></tbody></table></div></section></template>
